"""Generates tests/fixtures/differential.man for the etw-rs differential tests.

Run from the repo root:

    python tests/fixtures/generate_differential_manifest.py
    mc.exe -um tests/fixtures/differential.man -r <tmp> -h <tmp>

Every manifest in-type except win:CountedUnicodeString, win:CountedAnsiString and
win:CountedBinary is emitted in seven shapes. They are not a cross-product: each
varies one axis from a baseline, because the parser's offset walk, its
per-property size computation and its container walks fail independently.

    offset axis     First, Fixed, Dynamic, Last
    multiplicity    ArrayFixed, ArrayParamCount
    container       StructMember

Event id is BASE_ID + type_index * len(SHAPES) + shape_index. `subjects()` in
tests/differential_offline.rs must list types in this same order; the test
`subject_in_types_match_the_manifest` asks TDH which in-type it actually resolved
for each fixture and fails if the two lists drift.
"""

# (symbol suffix, manifest inType, extra attributes)
TYPES = [
    ("Int8", "win:Int8", ""),
    ("UInt8", "win:UInt8", ""),
    ("Int16", "win:Int16", ""),
    ("UInt16", "win:UInt16", ""),
    ("Int32", "win:Int32", ""),
    ("UInt32", "win:UInt32", ""),
    ("Int64", "win:Int64", ""),
    ("UInt64", "win:UInt64", ""),
    ("Float", "win:Float", ""),
    ("Double", "win:Double", ""),
    ("Boolean", "win:Boolean", ""),
    ("Guid", "win:GUID", ""),
    ("Pointer", "win:Pointer", ""),
    ("FileTime", "win:FILETIME", ""),
    ("SystemTime", "win:SYSTEMTIME", ""),
    ("Sid", "win:SID", ""),
    ("HexInt32", "win:HexInt32", ""),
    ("HexInt64", "win:HexInt64", ""),
    ("UnicodeString", "win:UnicodeString", ""),
    ("AnsiString", "win:AnsiString", ""),
    ("BinaryFixed", "win:Binary", ' length="4"'),
]

# Shapes, in the order their index is derived from. Do not reorder without
# regenerating and updating the Rust side.
SHAPES = [
    "First",
    "Fixed",
    "Dynamic",
    "Last",
    "ArrayFixed",
    "ArrayParamCount",
    "StructMember",
]

BASE_ID = 100
ARRAY_COUNT = 3

HEADER = '''<?xml version="1.0" encoding="utf-8"?>
<!--
  Test-only instrumentation manifest for the offline differential parser tests.
  GENERATED by tests/fixtures/generate_differential_manifest.py — do not hand-edit;
  regenerate, so every type keeps the same set of shapes.

  Never installed with `wevtutil im`. The test process calls TdhLoadManifest() on
  this file, which registers the schema for that process only and needs no
  elevation, so the tests run as ordinary unit tests.

  `Sentinel` is a fixed magic (0x5A5AA5A5) asserted on every fixture, so an over- or
  under-read corrupts it rather than landing silently in an unasserted field. `Lead`
  pushes the subject to an odd offset, so a parser assuming natural alignment fails.

  Each type appears in seven shapes, each varying one axis from a baseline.

  Offset axis — where the subject sits, and hence which predecessors it must fold:

    <Type>First       Subject | Sentinel
                      Offset zero, naturally aligned, no predecessor at all.
    <Type>Fixed       Lead | Subject | Sentinel
                      Constant but odd offset.
    <Type>Dynamic     Lead | Pad(UnicodeString) | Subject | Sentinel
                      Offset depends on Pad's run-time length, so no precomputed
                      constant satisfies it.
    <Type>Last        Lead | Sentinel | Subject
                      Nothing follows. A parser that runs a trailing field to the end
                      of the buffer regardless of its declared length passes the other
                      three and fails only this one.

  Multiplicity axis — element striding is its own computation, and differs between
  fixed-size elements (constant stride) and variable-size ones (re-scan per element):

    <Type>ArrayFixed        Lead | Subject[3] | Sentinel
    <Type>ArrayParamCount   Lead | SubjectCount | Subject[SubjectCount] | Sentinel
                            Also carries the count == 0 case, from the fixture side.

  Container axis — struct members are reached through struct_start_index /
  struct_member_count, a different walk from the top-level one:

    <Type>StructMember      Lead | { MemberU32, Subject } | Sentinel
-->
<instrumentationManifest
    xmlns="http://schemas.microsoft.com/win/2004/08/events"
    xmlns:win="http://manifests.microsoft.com/win/2004/08/windows/events"
    xmlns:xs="http://www.w3.org/2001/XMLSchema">
  <instrumentation>
    <events>
      <provider name="Etw-Rs-Differential"
                guid="{6f5b3a21-9c4e-4d17-b8a6-2e7f10c4d983}"
                symbol="ETW_RS_DIFFERENTIAL"
                resourceFileName="etw-rs-differential.dll"
                messageFileName="etw-rs-differential.dll">
        <templates>
'''

LINKAGE_TEMPLATES = '''
          <!-- Shapes that are not single types: length/count linkage, structs, and
               string-pair ordering. -->
          <template tid="T_ParamLength">
            <data name="Lead" inType="win:UInt8"/>
            <data name="SubjectLen" inType="win:UInt16"/>
            <data name="Subject" inType="win:Binary" length="SubjectLen"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_ParamCount">
            <data name="Lead" inType="win:UInt8"/>
            <data name="SubjectCount" inType="win:UInt16"/>
            <data name="Subject" inType="win:UInt32" count="SubjectCount"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_ParamLengthAfterVariable">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <data name="SubjectLen" inType="win:UInt16"/>
            <data name="Subject" inType="win:Binary" length="SubjectLen"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_ParamCountAfterVariable">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <data name="SubjectCount" inType="win:UInt16"/>
            <data name="Subject" inType="win:UInt32" count="SubjectCount"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_TwoStrings">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <data name="StrB" inType="win:UnicodeString"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_AnsiThenUnicode">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:AnsiString"/>
            <data name="StrB" inType="win:UnicodeString"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_UnicodeThenAnsi">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <data name="StrB" inType="win:AnsiString"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_StringThenSid">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <data name="Subject" inType="win:SID"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_StructAfterVariable">
            <data name="Lead" inType="win:UInt8"/>
            <data name="StrA" inType="win:UnicodeString"/>
            <struct name="Nested">
              <data name="MemberU32" inType="win:UInt32"/>
              <data name="MemberStr" inType="win:UnicodeString"/>
            </struct>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_StructFirst">
            <struct name="Nested">
              <data name="MemberU32" inType="win:UInt32"/>
              <data name="MemberStr" inType="win:UnicodeString"/>
            </struct>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_ParamLengthStaticCount">
            <data name="Lead" inType="win:UInt8"/>
            <data name="SubjectLen" inType="win:UInt16"/>
            <data name="Subject" inType="win:Binary" length="SubjectLen" count="2"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
          <template tid="T_ParamLengthAndCount">
            <data name="Lead" inType="win:UInt8"/>
            <data name="SubjectLen" inType="win:UInt16"/>
            <data name="SubjectCount" inType="win:UInt16"/>
            <data name="Subject" inType="win:Binary" length="SubjectLen" count="SubjectCount"/>
            <data name="Sentinel" inType="win:UInt32"/>
          </template>
'''

LINKAGE_EVENTS = [
    ("T_ParamLength", "E_PARAMLENGTH", 40),
    ("T_ParamCount", "E_PARAMCOUNT", 41),
    ("T_TwoStrings", "E_TWOSTRINGS", 42),
    ("T_AnsiThenUnicode", "E_ANSITHENUNICODE", 43),
    ("T_StringThenSid", "E_STRINGTHENSID", 44),
    ("T_StructAfterVariable", "E_STRUCTAFTERVARIABLE", 45),
    ("T_UnicodeThenAnsi", "E_UNICODETHENANSI", 53),
    ("T_ParamLengthAfterVariable", "E_PARAMLENGTHAFTERVARIABLE", 54),
    ("T_ParamCountAfterVariable", "E_PARAMCOUNTAFTERVARIABLE", 55),
    ("T_StructFirst", "E_STRUCTFIRST", 56),
    ("T_ParamLengthAndCount", "E_PARAMLENGTHANDCOUNT", 57),
    ("T_ParamLengthStaticCount", "E_PARAMLENGTHSTATICCOUNT", 58),
]

LEAD = '<data name="Lead" inType="win:UInt8"/>'
SENT = '<data name="Sentinel" inType="win:UInt32"/>'
PAD = '<data name="Pad" inType="win:UnicodeString"/>'


def rows_for(in_type, extra, shape):
    def subj(more=""):
        return '<data name="Subject" inType="{}"{}{}/>'.format(in_type, extra, more)

    if shape == "First":
        return [subj(), SENT]
    if shape == "Fixed":
        return [LEAD, subj(), SENT]
    if shape == "Dynamic":
        return [LEAD, PAD, subj(), SENT]
    if shape == "Last":
        return [LEAD, SENT, subj()]
    if shape == "ArrayFixed":
        return [LEAD, subj(' count="{}"'.format(ARRAY_COUNT)), SENT]
    if shape == "ArrayParamCount":
        return [
            LEAD,
            '<data name="SubjectCount" inType="win:UInt16"/>',
            subj(' count="SubjectCount"'),
            SENT,
        ]
    if shape == "StructMember":
        return [
            LEAD,
            '<struct name="Nested">',
            '  <data name="MemberU32" inType="win:UInt32"/>',
            "  " + subj(),
            "</struct>",
            SENT,
        ]
    raise AssertionError("unknown shape " + shape)


def template(sym, in_type, extra, shape):
    body = "\n".join("            " + r for r in rows_for(in_type, extra, shape))
    return '          <template tid="T_{}{}">\n{}\n          </template>\n'.format(
        sym, shape, body
    )


out = [HEADER]
ids = []
for i, (sym, in_type, extra) in enumerate(TYPES):
    for j, shape in enumerate(SHAPES):
        out.append(template(sym, in_type, extra, shape))
        ids.append((sym, shape, BASE_ID + i * len(SHAPES) + j))
out.append(LINKAGE_TEMPLATES)
out.append("        </templates>\n\n        <events>\n")
for sym, shape, eid in ids:
    out.append(
        '          <event value="{}" version="0" level="win:Informational" '
        'template="T_{}{}" symbol="E_{}_{}"/>\n'.format(
            eid, sym, shape, sym.upper(), shape.upper()
        )
    )
out.append("\n")
for tid, symbol, eid in LINKAGE_EVENTS:
    out.append(
        '          <event value="{}" version="0" level="win:Informational" '
        'template="{}" symbol="{}"/>\n'.format(eid, tid, symbol)
    )
out.append("""        </events>
      </provider>
    </events>
  </instrumentation>
</instrumentationManifest>
""")

open("tests/fixtures/differential.man", "w", encoding="utf-8", newline="\n").write(
    "".join(out)
)
print(
    "types={} shapes={} shape_events={} linkage_events={} total={}".format(
        len(TYPES),
        len(SHAPES),
        len(ids),
        len(LINKAGE_EVENTS),
        len(ids) + len(LINKAGE_EVENTS),
    )
)
print("id stride per type = {}; Int8 ids: {}".format(len(SHAPES), [e for _, _, e in ids[:7]]))
